js.home:
const page = Number(env.get('page', 1) || 1);
const url = page <= 1 ? `${env.baseUrl}/anime/ai/` : `${env.baseUrl}/anime/ai/page/${page}/`;
const html = await req(url);
const out = [];
const seen = {};
const re = /<a[^>]*href="(\/anime\/ai\/(\d+)\/)"[^>]*>([\s\S]*?)<\/a>/g;
let m;
while ((m = re.exec(html)) && out.length < 100) {
  const id = m[2];
  if (seen[id]) continue;
  seen[id] = 1;
  const inner = m[3];
  const cm = inner.match(/data-src="([^"]*)"/) || inner.match(/src="([^"]*upload[^"]*)"/);
  const cover = cm ? cm[1] : '';
  const am = inner.match(/alt="([^"]*)"/);
  let title = am ? am[1] : '';
  if (!title) title = inner.replace(/<[^>]+>/g, ' ').trim();
  if (title && title.length > 1) {
    out.push({ id: '/anime/ai/' + id + '/', title, cover, remark: 'AI漫剧' });
  }
}
return out;

js.detail:
let id = env.get('movieId', '');
if (!id) return { id: '', title: '', cover: '', playlist: [] };
const idm = String(id).match(/(\d+)/);
if (idm) id = idm[1];
const jsonStr = await req(`${env.baseUrl}/api/dm/anime/${id}/`);
const data = JSON.parse(jsonStr).data;
const eps = (data.episodes || []).map(ep => {
  const n = ep.sort_no || (ep.index + 1) || 1;
  const label = ep.label || ('EP' + String(n).padStart(2, '0'));
  const t = ep.title ? (' ' + ep.title) : '';
  return { text: label + t, url: `${env.baseUrl}/api/dm/anime/${id}/episodes/${n}/stream` };
});
if (!eps.length) {
  eps.push({ text: 'EP01', url: `${env.baseUrl}/api/dm/anime/${id}/episodes/1/stream` });
}
return {
  id: '/anime/ai/' + id + '/',
  title: data.title || '',
  cover: data.cover || '',
  remark: 'AI漫剧',
  desc: data.intro || '',
  playlist: [{ title: '默认线路', videos: eps }]
};

